        elif item[0] == '-':
            self.rarity = Rarity.rare
        else:
            self.rarity = Rarity.legendary

        try:
            self.light = int(item[1:] if self.rarity is not Rarity.legendary else item)
        except ValueError as e:
            raise Exception("Invalid item {}; items must be integers.".format(str(e).split()[-1]))

    def __repr__(self):
        return str(self.light)

class Path:
    COST = 3

    @staticmethod
    def infuse(base, target):
        diff = target.light - base.light
        comp = 4 if base.rarity is Rarity.exotic else 6
        perc = 0.7 if base.rarity is Rarity.exotic else 0.8

        if diff <= comp:
            return Item(target.light, base.rarity)
        else:
            return Item(base.light + round(diff * perc), base.rarity)

    def __init__(self, steps):
        self.steps = steps
        self.cost = (len(steps) - 1) * Path.COST
        self.item = functools.reduce(Path.infuse, steps)
        self.light = self.item.light

class Paths:
    def __init__(self, base, items):
        self.base = Item(base)
        self.items = Paths.prune(self.base, items)
        self.target = self.items[-1]
        self.others = self.items[:-1]
        perms = Paths.permutate(self.base, self.others, self.target)
        self.paths = sorted([Path(perm) for perm in perms], key=lambda path: path.light)
        self.best_light = self.least_cost = self.paths[0]

        for path in self.paths:
            if (path.light > self.best_light.light or
                    (path.light == self.best_light.light and path.cost < self.best_light.cost)):
                self.best_light = path

            if (path.cost < self.least_cost.cost or
                    (path.cost == self.least_cost.cost and path.light > self.least_cost.light)):
                self.least_cost = path

    @staticmethod
    def prune(base, items):
        pruned = [item for item in sorted(map(Item, items), key=lambda item: item.light) if item.light > base.light]
        if len(pruned) == 0:
            raise Exception("Base item is highest light level")
        return pruned

    @staticmethod
    def permutate(low, mid, high):
        perms = [[low, high]]
        for l in range(1, len(mid) + 1):
            for perm in itertools.combinations(mid, l):
                perms.append(list(itertools.chain([low], perm, [high])))
        return perms

# main function
def main_solution(base_item, item_list):
    # Convert input strings to appropriate types
    base_item = str(base_item)
    item_list = list(map(str, item_list))

    # Create Paths object to find the best light and least cost paths
    paths = Paths(base_item, item_list)

    # Return the best light and least cost paths as dictionaries
    return {
        "best_light": paths.best_light.light,
        "least_cost": paths.least_cost.cost
    }

