# import necessary packages
from math import exp
import random

# all class and function definitions in the code file, if any
def compute_evolving_probabilities(k, d):
    exponent1 = -4.0 * d / (k + 2)
    exponent2 = -2.0 * d * ((k + 1) / (k + 2))
    probability_no_change = 0.25 * (1.0 + exp(exponent1)) + 0.5 * exp(exponent2)
    probability_transition = 0.25 * (1.0 + exp(exponent1)) - 0.5 * exp(exponent2)
    probability_transversion = 0.25 * (1.0 - exp(exponent1))
    return probability_no_change, probability_transition, probability_transversion

def pick_character_evolution(prob_no_change, prob_transt, prob_transv):
    random_number = random.random()
    if random_number <= prob_transv:
        return "TRV1"
    elif random_number <= 2 * prob_transv:
        return "TRV2"
    elif random_number <= prob_transt + 2 * prob_transv:
        return "TRS"
    else:
        return "NOCH"

def pick_evolved_character(current_character, evolution_action):
    if evolution_action == "NOCH":
        return current_character
    elif evolution_action == "TRV1":
        if current_character in "AG":
            return "T"
        else:
            return "A"
    elif evolution_action == "TRV2":
        if current_character in "AG":
